'use strict';

function validateWorkshopRequest(topic, seatCount, facilitatorId) {
  if (typeof topic !== 'string') {
    throw new TypeError('topic must be a string');
  }
  const cleanTopic = topic.trim();
  if (cleanTopic.length === 0 || cleanTopic.length > 80) {
    throw new RangeError('topic must contain 1 to 80 UTF-16 code units');
  }

  if (typeof seatCount !== 'number' || !Number.isInteger(seatCount)) {
    throw new TypeError('seatCount must be an integer');
  }
  if (seatCount < 2 || seatCount >= 40) {
    throw new RangeError('seatCount must be from 2 through 40');
  }

  if (typeof facilitatorId !== 'string') {
    throw new TypeError('facilitatorId must be a string');
  }
  const cleanId = facilitatorId.trim();
  if (!/^fac-[0-9]{6}$/.test(cleanId)) {
    throw new RangeError('facilitatorId has an invalid format');
  }

  return {
    isValid: true,
    data: { topic: cleanTopic, seatCount, facilitatorId: cleanId }
  };
}

module.exports = { validateWorkshopRequest };

