'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['validateWorkshopRequest']);
const { validateWorkshopRequest } = api;

assert.deepStrictEqual(validateWorkshopRequest('  Distributed Systems  ', 2, '  fac-012345  '), {
  isValid: true,
  data: { topic: 'Distributed Systems', seatCount: 2, facilitatorId: 'fac-012345' }
});
assert.deepStrictEqual(validateWorkshopRequest('x'.repeat(80), 40, 'fac-999999'), {
  isValid: true,
  data: { topic: 'x'.repeat(80), seatCount: 40, facilitatorId: 'fac-999999' }
});
assert.deepStrictEqual(validateWorkshopRequest('😀'.repeat(40), 10, 'fac-000000').data.topic, '😀'.repeat(40));
assert.throws(() => validateWorkshopRequest('😀'.repeat(41), 10, 'fac-000000'), error => error instanceof RangeError && /topic/.test(error.message));

for (const topic of [null, undefined, 3, {}, []]) {
  assert.throws(() => validateWorkshopRequest(topic, 10, 'fac-123456'), error => error instanceof TypeError && /topic/.test(error.message));
}
for (const topic of ['', '   ', 'x'.repeat(81)]) {
  assert.throws(() => validateWorkshopRequest(topic, 10, 'fac-123456'), error => error instanceof RangeError && /topic/.test(error.message));
}
for (const seats of [null, '2', {}, 2.5]) {
  assert.throws(() => validateWorkshopRequest('Topic', seats, 'fac-123456'), error => error instanceof TypeError && /seatCount/.test(error.message));
}
for (const seats of [1, 41, -2]) {
  assert.throws(() => validateWorkshopRequest('Topic', seats, 'fac-123456'), error => error instanceof RangeError && /seatCount/.test(error.message));
}
for (const id of [null, 123456, {}, []]) {
  assert.throws(() => validateWorkshopRequest('Topic', 10, id), error => error instanceof TypeError && /facilitatorId/.test(error.message));
}
for (const id of ['', 'fac-12345', 'fac-1234567', 'FAC-123456', 'fac-12a456', 'x-fac-123456']) {
  assert.throws(() => validateWorkshopRequest('Topic', 10, id), error => error instanceof RangeError && /facilitatorId/.test(error.message));
}
let error;
try { validateWorkshopRequest(7, 'bad', null); } catch (caught) { error = caught; }
assert.ok(error instanceof TypeError);
assert.match(error.message, /topic/);
const first = validateWorkshopRequest('Topic', 10, 'fac-123456');
const second = validateWorkshopRequest('Topic', 10, 'fac-123456');
assert.notStrictEqual(first, second);
assert.notStrictEqual(first.data, second.data);

